INSERT INTO kb_chunks (document_id, chunk_index, section_path, title_context, content, summary, preset_questions, physical_context, token_count) VALUES
((SELECT id FROM kb_documents WHERE title = '液压系统维护手册' LIMIT 1), 0, '设备维护 > 液压系统 > 压力不足', '液压系统维护手册 - 压力不足故障排查', '当液压泵压力不足时，应优先检查过滤器是否堵塞。过滤器堵塞会导致油液无法正常循环，造成压力上不去的问题。其次检查油液液位是否正常，如果油液太少也会影响压力输出。最后检查泄压阀和液压阀是否工作正常。', '说明液压泵压力不足时的优先检查项。', '["液压泵压力不足怎么办？", "设备压力上不去应该先查哪里？", "过滤器堵塞会不会影响液压压力？"]'::JSONB, '{"page": 18, "image_refs": ["hydraulic_filter_001"]}'::JSONB, 250),
((SELECT id FROM kb_documents WHERE title = '液压系统维护手册' LIMIT 1), 1, '设备维护 > 液压系统 > 维护周期', '液压系统维护手册 - 维护周期', '液压系统的维护周期一般为3个月进行一次常规检查，每6个月进行一次深度维护。常规检查包括更换过滤器、检查油液液位、观察系统运行状态。', '说明液压系统的维护周期和内容。', '["液压系统多久维护一次？", "维护液压系统需要做什么？"]'::JSONB, '{"page": 5, "image_refs": []}'::JSONB, 180),
((SELECT id FROM kb_documents WHERE title = '生产质量管理规范' LIMIT 1), 0, '质量管理 > 异常处理', '生产质量管理规范 - 异常处理流程', '当检测到产品质量异常时，应立即停止生产线，记录异常现象，通知质量负责人，进行原因分析和纠正措施。', '说明质量异常处理的基本流程。', '["质量异常处理流程是什么？", "检测到不良品怎么办？"]'::JSONB, '{"page": 1, "image_refs": []}'::JSONB, 200);